const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
let role=localStorage.role||'operator';if(!R[role])role='operator';const r=R[role];
function cur(){return{n:r.n,alias:r.alias||r.n,dept:(DB.people.find(p=>p.role===role)||{}).dept||'D5'}}
function deptName(id){const d=DB.depts.find(x=>x.id===id);return d?d.name:id}
function lineName(id){return{L1:'大连一厂 · Line A',L2:'大连一厂 · Line B',L3:'苏州二厂 · Line C',L4:'青岛三厂 · 装配线'}[id]||id}
const ACC=['#0aa68f','#1f7ec2','#7c5cbf','#f39446','#e4525a','#c2951f'];
function avatar(n){n=String(n||'?');if(window.AVA&&window.AVA[n])return `<i class="avatar"><img src="${window.AVA[n]}" alt=""></i>`;let h=0;for(const c of n)h=(h*31+c.charCodeAt(0))>>>0;const c=ACC[h%ACC.length];const t=n.replace(/[^A-Za-z\u4e00-\u9fa5]/g,'').slice(-2)||'?';return `<i class="avatar" style="--a:${c}">${esc(t)}</i>`}
function loadAvatars(){try{window.AVA=JSON.parse(localStorage.getItem('ai.avatars')||'{}')}catch(e){window.AVA={}}}
function upAvatar(inp){const f=inp.files&&inp.files[0];if(!f)return;if(f.size>4*1024*1024)return toast('图片过大，请小于 4MB');const rd=new FileReader();rd.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=c.height=128;const g=c.getContext('2d');const s=Math.min(img.width,img.height);g.drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,0,0,128,128);const d=c.toDataURL('image/jpeg',.82);let A={};try{A=JSON.parse(localStorage.getItem('ai.avatars')||'{}')}catch(e){}A[r.alias]=d;localStorage.setItem('ai.avatars',JSON.stringify(A));loadAvatars();audit('头像更新',r.alias);toast('头像已更新');render()};img.onerror=()=>toast('图片解析失败');img.src=rd.result};rd.readAsDataURL(f)}
function rmAvatar(){let A={};try{A=JSON.parse(localStorage.getItem('ai.avatars')||'{}')}catch(e){}delete A[r.alias];localStorage.setItem('ai.avatars',JSON.stringify(A));loadAvatars();toast('已恢复默认头像');render()}
function mePage(){const me=cur();const p=DB.people.find(x=>x.role===role)||{};const myDone=DB.tasks.filter(t=>t.who===r.alias&&t.status==='完成').length;const myUse=DB.tasks.length;return head('我的','个人资料、头像与使用统计。')+`<div class="grid2"><div class="card me-card"><div class="me-ava">${avatar(r.alias)}</div><h3>${esc(r.n)}</h3><p class="dim">${esc(r.d)} · ${ROLENAME[role]}</p><div class="field"><label>上传头像（自动裁剪为圆形）<input type="file" accept="image/*" onchange="upAvatar(this)"></label></div><button class="btn ghost sm2" onclick="rmAvatar()">恢复默认头像</button></div><div class="card"><h3>我的信息</h3><table class="table"><tr><th>项目</th><th>内容</th></tr><tr><td>部门</td><td>${deptName(me.dept)}</td></tr><tr><td>角色</td><td>${ROLENAME[role]}</td></tr><tr><td>技能</td><td>${esc(p.skills||'--')}</td></tr><tr><td>工位授权</td><td>${esc(p.st||'--')}</td></tr><tr><td>状态</td><td>${p.on?'<span class="badge">在线</span>':'<span class="badge dim">离线</span>'}</td></tr></table><h3>我的统计</h3><p>完成任务 <b>${myDone}</b> 单 · 关联任务 <b>${myUse}</b> 单 · 头像在流程与布局中同步显示</p></div></div>`}
function sbadge(st){const m={'完成':'','作业中':'warn','异常':'danger','未开始':'dim','进行中':'warn','待响应':'danger','已解决':'','启用':'','审核中':'warn','废弃':'dim','已发布':'','草稿':'dim','产线实例':'warn','待分配':'dim'};return `<span class="badge ${m[st]||''}">${st}</span>`}
