function table(cols,rows){return `<div class="card"><table class="table"><tr>${cols.map(c=>`<th>${c}</th>`).join('')}</tr>${rows.join('')||'<tr><td colspan="9" class="empty">暂无数据</td></tr>'}</table></div>`}
function chips(cur,items,fn){return `<div class="chips">${items.map(i=>`<button class="chip${i===cur?' on':''}" onclick="${fn}('${i}')">${i}</button>`).join('')}</div>`}
function modal(html){let m=document.getElementById('modal');if(!m){m=document.createElement('div');m.id='modal';document.body.appendChild(m)}m.innerHTML=`<div class="mask" onclick="if(event.target===this)closeModal()"></div><div class="mbox"><div class="mhead"><b>操作面板</b><button class="mx" onclick="closeModal()">×</button></div>${html}</div>`;m.classList.add('open')}
function closeModal(){const m=document.getElementById('modal');if(m)m.classList.remove('open')}
function dayDetail(l,sName,v){const i=D30.indexOf(l);const metrics=[['任务完成量',TR.tasks[i]],['一次合格率 %',TR.acc[i]],['知识新增',TR.kn[i]],['审批量',TR.appr[i]]];modal(`<h3>${esc(l)} · 当日详情</h3><p class="dim">点击来源：${esc(sName)} = <b>${esc(v)}</b></p><table class="table"><tr><th>指标</th><th>数值</th></tr>${metrics.map(m=>`<tr><td>${m[0]}</td><td><b>${m[1]}</b></td></tr>`).join('')}</table><h3>当日任务</h3><table class="table"><tr><th>任务</th><th>工位/工序</th><th>状态</th></tr>${DB.tasks.slice(0,6).map(t=>`<tr><td>${esc(t.name)}</td><td>${t.st} · ${t.op}</td><td>${sbadge(t.status)}</td></tr>`).join('')}</table><p class="dim">趋势为演示数据；此页面由图上数据点点击进入。</p>`)}
function toast(msg){let t=document.getElementById('gtoast');if(!t){t=document.createElement('div');t.id='gtoast';document.body.appendChild(t)}t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2000)}
function hbars(data){const max=Math.max(...data.map(d=>d[1]))||1;return data.map(d=>`<div class="hbar"><span>${esc(d[0])}</span><div class="hb-t"><i style="width:${(d[1]/max*100).toFixed(0)}%"></i></div><b>${d[1]}%</b></div>`).join('')}
function lineChart(labels,series,ch){const w=680,h=ch||230,pl=42,pr=14,pt=18,pb=26;const all=series.flatMap(s=>s.data);let min=Math.min(...all),max=Math.max(...all);if(max-min<1){max+=1;min-=1}min=min-(max-min)*.08;max=max+(max-min)*.08;const X=i=>pl+i*(w-pl-pr)/(labels.length-1),Y=v=>h-pb-(v-min)/(max-min)*(h-pt-pb);let g='';for(let i=0;i<=4;i++){const y=pt+i*(h-pt-pb)/4,v=(max-(max-min)*i/4).toFixed(0);g+=`<line x1="${pl}" y1="${y}" x2="${w-pr}" y2="${y}" stroke="#e2ecef"/><text x="${pl-6}" y="${+y+4}" text-anchor="end" font-size="10" fill="#8a9ea9">${v}</text>`}let xl='';const step=Math.ceil(labels.length/8)||1;labels.forEach((l,i)=>{if(i%step===0)xl+=`<text x="${X(i)}" y="${h-8}" text-anchor="middle" font-size="10" fill="#8a9ea9">${l}</text>`});const body=series.map(s=>{const pts=s.data.map((v,i)=>X(i)+','+Y(v)).join(' ');const dots=s.data.map((v,i)=>`<circle class="cpt" data-l="${labels[i]}" data-s="${s.n}" data-v="${v}" cx="${X(i)}" cy="${Y(v)}" r="3.4" fill="${s.c}" stroke="#fff" stroke-width="1.2"/>`).join('');return `<polyline points="${pts}" fill="none" stroke="${s.c}" stroke-width="2.5"/>${dots}`}).join('');const lg=series.map((s,i)=>`<g><rect x="${pl+i*130}" y="2" width="10" height="10" rx="2" fill="${s.c}"/><text x="${pl+i*130+15}" y="11" font-size="11" fill="#365462">${s.n}</text></g>`).join('');return `<svg class="chart" viewBox="0 0 ${w} ${h}">${g}${xl}${body}${lg}</svg>`}
function barChart(labels,data,color){const w=680,h=200,pl=34,pb=24,max=Math.max(...data)*1.15||1;const bw=(w-pl-14)/labels.length;let b='',xl='';labels.forEach((l,i)=>{const bh=data[i]/max*(h-pb-14);b+=`<rect x="${pl+i*bw+3}" y="${h-pb-bh}" width="${bw-6}" height="${bh}" rx="3" fill="${color}" opacity=".85"><title>${l}：${data[i]}</title></rect>`;if(i%Math.ceil(labels.length/10)===0)xl+=`<text x="${pl+i*bw+bw/2}" y="${h-8}" text-anchor="middle" font-size="9" fill="#8a9ea9">${l}</text>`});return `<svg class="chart" viewBox="0 0 ${w} ${h}"><line x1="${pl}" y1="${h-pb}" x2="${w-10}" y2="${h-pb}" stroke="#e2ecef"/>${b}${xl}</svg>`}
const D30=(()=>{const o=[];for(let i=29;i>=0;i--){const d=new Date(2026,10,26);d.setDate(d.getDate()-i);o.push((d.getMonth()+1)+'/'+d.getDate())}return o})();
const TR={tasks:gen(30,38,26,7),acc:gen(30,92.5,5.5,11,1),kn:gen(30,1,7,23),appr:gen(30,4,9,5)};
const LTR={busy:gen(30,3,5,31),idle:gen(30,2,4,37),exc:gen(30,0,3,41),acc:gen(30,91,6,43,1)};
const CT={zone:{l:'产线区',c:'#0aa68f',s:'rect',w:200},station:{l:'工位',c:'#1f7ec2',s:'rect'},equipment:{l:'设备',c:'#7c5cbf',s:'rect'},storage:{l:'仓储区',c:'#c2951f',s:'rect',w:170},qc:{l:'质检区',c:'#f39446',s:'diamond',w:110},gate:{l:'出入口',c:'#718590',s:'pill',w:120},start:{l:'开始',c:'#0aa68f',s:'pill',w:110},op:{l:'工序',c:'#1f7ec2',s:'rect'},approval:{l:'审批',c:'#f39446',s:'diamond',w:110},decision:{l:'判断',c:'#c2951f',s:'diamond',w:110},rework:{l:'返工',c:'#e8743f',s:'rect'},sos:{l:'SOS',c:'#e4525a',s:'rect'},end:{l:'结束',c:'#718590',s:'pill',w:110}};
const CP={layout:['zone','station','equipment','storage','qc','gate'],flow:['start','op','approval','decision','rework','sos','end']};
const CSEED={
layout:{n:[{id:'a',t:'zone',x:40,y:40,n:'一区 · CNC产线'},{id:'b',t:'station',x:80,y:170,n:'ST-01 上料'},{id:'c',t:'station',x:300,y:170,n:'ST-02 钻孔'},{id:'d',t:'equipment',x:140,y:330,n:'VCN-530C'},{id:'e',t:'qc',x:520,y:170,n:'质检区'},{id:'f',t:'storage',x:40,y:450,n:'原材料仓'},{id:'g',t:'gate',x:700,y:450,n:'南门'}],e:[{id:'e1',from:'f',to:'b'},{id:'e2',from:'b',to:'c'},{id:'e3',from:'d',to:'c'},{id:'e4',from:'c',to:'e'},{id:'e5',from:'e',to:'g'}]},
flow:{n:[{id:'s',t:'start',x:20,y:230,n:'开始'},{id:'o1',t:'op',x:150,y:140,n:'OP10 上料'},{id:'o2',t:'op',x:340,y:140,n:'OP20 钻孔'},{id:'o3',t:'op',x:530,y:140,n:'OP30 精铣'},{id:'ap',t:'approval',x:530,y:340,n:'首件审批'},{id:'o4',t:'op',x:720,y:140,n:'OP40 品质'},{id:'rw',t:'rework',x:720,y:340,n:'返工至OP20'},{id:'so',t:'sos',x:340,y:340,n:'SOS 升级'},{id:'x',t:'end',x:900,y:140,n:'结束'}],e:[{id:'e1',from:'s',to:'o1'},{id:'e2',from:'o1',to:'o2'},{id:'e3',from:'o2',to:'o3'},{id:'e4',from:'o3',to:'o4'},{id:'e5',from:'o4',to:'x'},{id:'e6',from:'o3',to:'ap'},{id:'e7',from:'ap',to:'o4'},{id:'e8',from:'o4',to:'rw'},{id:'e9',from:'rw',to:'o2'},{id:'e10',from:'o2',to:'so'}]}};
let __cvOpts=null;
function editor(k,opts={}){__cvOpts=Object.assign({key:k,pk:k,seed:null,onSave:null},opts);const pal=CP[k]||CP.flow;const name=opts.doc?`<input id="cv-docname" class="cv-docname" value="${esc(opts.doc.name)}" title="文档名称">`:'';return `<div class="cv-bar">${name}${pal.map(t=>`<button class="btn ghost cv-add" data-t="${t}" style="--c:${CT[t].c}">＋${CT[t].l}</button>`).join('')}<span class="cv-hint">拖拽移动 · 圆点拉线 · 双击改名 · Delete 删除 · Ctrl+Z 撤销</span><button class="btn ghost" id="cv-clear">清空</button><button class="btn" id="cv-save">保存</button></div><div class="cv-main"><div class="cv-stage" id="cv-stage"><svg class="cv-svg" id="cv-svg"><defs><marker id="cv-arr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#5b7684"/></marker><marker id="cv-arr-s" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#e4525a"/></marker></defs><g id="cv-edges"></g></svg><div id="cv-nodes"></div></div><aside class="cv-props" id="cv-props"></aside></div><div class="cv-toast" id="cv-toast"></div>`}
function Canvas(o){
const pk=o.pk,pal=CP[pk]||CP.flow;
const stage=document.getElementById('cv-stage'),gE=document.getElementById('cv-edges'),gN=document.getElementById('cv-nodes'),props=document.getElementById('cv-props'),tt=document.getElementById('cv-toast');
let D,sel=null,hist=[],uid=0,timer=null;
const clone=x=>JSON.parse(JSON.stringify(x)),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),g20=v=>Math.round(v/20)*20,find=id=>D.n.find(x=>x.id===id);
function initData(){let s=null;try{s=localStorage.getItem('cv.'+o.key)}catch(e){}const d=s?JSON.parse(s):clone(o.seed||CSEED[pk]||CSEED.flow);d.n=d.n||[];d.e=d.e||[];return d}
D=initData();uid=D.n.length+D.e.length+20;
const persist=()=>{try{localStorage.setItem('cv.'+o.key,JSON.stringify(D))}catch(e){}if(o.onSave)o.onSave()};
const persistSoon=()=>{clearTimeout(timer);timer=setTimeout(persist,300)};
const snap=()=>{hist.push(JSON.stringify({n:D.n,e:D.e}));if(hist.length>60)hist.shift()};
function toast2(m){tt.textContent=m;tt.classList.add('show');clearTimeout(toast2.t);toast2.t=setTimeout(()=>tt.classList.remove('show'),1600)}
function undo(){if(!hist.length)return toast2('没有可撤销的操作');const s=JSON.parse(hist.pop());D.n=s.n;D.e=s.e;sel=null;render();persist();toast2('已撤销')}
function geo(id){const el=gN.querySelector(`.cv-node[data-id="${id}"]`);return el?{x1:el.offsetLeft,y1:el.offsetTop,w:el.offsetWidth,h:el.offsetHeight,cx:el.offsetLeft+el.offsetWidth/2,cy:el.offsetTop+el.offsetHeight/2}:null}
function anchorPt(g,tg){const dx=tg.cx-g.cx,dy=tg.cy-g.cy;return Math.abs(dx)>=Math.abs(dy)?[dx>0?g.x1+g.w:g.x1,g.cy]:[g.cx,dy>0?g.y1+g.h:g.y1]}
function edgePath(e){const a=geo(e.from),b=geo(e.to);if(!a||!b)return'';const p1=anchorPt(a,b),p2=anchorPt(b,a),dx=(p2[0]-p1[0])*.38,dy=(p2[1]-p1[1])*.38;return`M${p1[0]} ${p1[1]} C${p1[0]+dx} ${p1[1]+dy} ${p2[0]-dx} ${p2[1]-dy} ${p2[0]} ${p2[1]}`}
function nodeHTML(n){const t=CT[n.t]||CT.op;return`<div class="cv-node sh-${t.s}" data-id="${n.id}" style="left:${n.x}px;top:${n.y}px;width:${t.w||150}px;--c:${t.c}">${n.a?`<i class="cv-ava" title="${esc(n.a)} 负责该工序">${esc(String(n.a).replace(/[^A-Za-z\u4e00-\u9fa5]/g,'').slice(-2))}</i>`:''}<span class="cv-tag">${t.l}</span><b class="cv-name" title="${esc(n.n)}">${esc(n.n)}</b>${n.d?`<small class="cv-note">${esc(n.d)}</small>`:''}<span class="cv-x" title="删除">×</span><i class="cv-port" data-p="l"></i><i class="cv-port" data-p="r"></i><i class="cv-port" data-p="t"></i><i class="cv-port" data-p="b"></i></div>`}
function renderNodes(){gN.innerHTML=D.n.map(nodeHTML).join('');gN.querySelectorAll('.cv-node').forEach(el=>{const n=find(el.dataset.id);el.addEventListener('pointerdown',ev=>startDrag(ev,el,n));const x=el.querySelector('.cv-x');x.addEventListener('pointerdown',ev=>ev.stopPropagation());x.addEventListener('click',ev=>{ev.stopPropagation();delNode(n.id)});el.addEventListener('dblclick',()=>rename(el,n));el.querySelectorAll('.cv-port').forEach(p=>p.addEventListener('pointerdown',ev=>startLink(ev,el,n)))})}
function renderEdges(){gE.innerHTML=D.e.map(e=>{const d=edgePath(e);return d?`<path class="cv-hit" d="${d}" data-id="${e.id}"/><path class="cv-edge${sel===e.id?' sel':''}" d="${d}" marker-end="url(#cv-arr${sel===e.id?'-s':''})"/>`:''}).join('');gE.querySelectorAll('.cv-hit').forEach(h=>h.addEventListener('pointerdown',ev=>{ev.stopPropagation();select(h.dataset.id)}))}
function paintSel(){gN.querySelectorAll('.cv-node').forEach(x=>x.classList.toggle('sel',x.dataset.id===sel))}
function render(){renderNodes();renderEdges();renderProps()}
function select(id){sel=id;paintSel();renderEdges();renderProps()}
function startDrag(ev,el,n){if(ev.target.closest('input,select,textarea'))return;if(ev.pointerType==='mouse'&&ev.button!==0)return;ev.stopPropagation();select(n.id);const sx=ev.clientX,sy=ev.clientY,ox=n.x,oy=n.y;let moved=false;
const mv=e=>{const dx=e.clientX-sx,dy=e.clientY-sy;if(!moved&&Math.abs(dx)+Math.abs(dy)<4)return;if(!moved){moved=true;snap()}n.x=clamp(g20(ox+dx),0,Math.max(0,stage.clientWidth-el.offsetWidth));n.y=clamp(g20(oy+dy),0,Math.max(0,stage.clientHeight-el.offsetHeight));el.style.left=n.x+'px';el.style.top=n.y+'px';renderEdges()};
const up=()=>{el.removeEventListener('pointermove',mv);el.removeEventListener('pointerup',up);if(moved)persistSoon()};
el.setPointerCapture(ev.pointerId);el.addEventListener('pointermove',mv);el.addEventListener('pointerup',up)}
function rename(el,n){const b=el.querySelector('.cv-name');if(!b||el.querySelector('input'))return;const i=document.createElement('input');i.className='cv-rename';i.value=n.n;b.style.display='none';el.appendChild(i);i.focus();i.select();let fin=false;
const done=ok=>{if(fin)return;fin=true;const v=i.value.trim();i.remove();b.style.display='';if(ok&&v&&v!==n.n){snap();n.n=v;persistSoon()}b.textContent=n.n;b.title=n.n;renderProps()};
i.addEventListener('blur',()=>done(true));
i.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Enter')done(true);else if(e.key==='Escape')done(false)})}
function startLink(ev,el,n){ev.stopPropagation();ev.preventDefault();const from=n.id,temp=document.createElementNS('http://www.w3.org/2000/svg','path');temp.setAttribute('class','cv-ghost');gE.appendChild(temp);
const mv=e=>{const rc=stage.getBoundingClientRect(),g=geo(from);if(g){const p=anchorPt(g,{cx:e.clientX-rc.left,cy:e.clientY-rc.top});temp.setAttribute('d',`M${p[0]} ${p[1]} L${e.clientX-rc.left} ${e.clientY-rc.top}`)}};
const up=e=>{document.removeEventListener('pointermove',mv);document.removeEventListener('pointerup',up);temp.remove();const t=document.elementFromPoint(e.clientX,e.clientY),nel=t&&t.closest?t.closest('.cv-node'):null;if(nel)addEdge(from,nel.dataset.id)};
document.addEventListener('pointermove',mv);document.addEventListener('pointerup',up)}
function addEdge(a,b){if(a===b)return toast2('不能连接到自身');if(D.e.some(x=>x.from===a&&x.to===b))return toast2('这两个组件已连接');snap();const id='e'+(++uid);D.e.push({id,from:a,to:b});select(id);persistSoon();toast2('已连接')}
function delNode(id){const n=find(id);if(!n)return;snap();D.n=D.n.filter(x=>x.id!==id);D.e=D.e.filter(x=>x.from!==id&&x.to!==id);if(sel===id)sel=null;render();persistSoon();toast2(`已删除「${n.n}」及其连线`)}
function delEdge(id){if(!D.e.some(x=>x.id===id))return;snap();D.e=D.e.filter(x=>x.id!==id);if(sel===id)sel=null;renderEdges();renderProps();persistSoon();toast2('已删除连线')}
function addNode(t){const c=CT[t];if(!c)return;snap();const cnt=D.n.filter(x=>x.t===t).length+1,id='n'+(++uid);D.n.push({id,t,x:clamp(g20(60+(D.n.length*53)%560),0,Math.max(0,stage.clientWidth-170)),y:clamp(g20(50+(D.n.length*37)%340),0,Math.max(0,stage.clientHeight-90)),n:c.l+(cnt>1?cnt:''),d:''});renderNodes();select(id);persistSoon();toast2(`已添加 ${c.l}`)}
function renderProps(){const nd=find(sel);
if(nd){const t=CT[nd.t]||CT.op,ci=D.e.filter(e=>e.to===nd.id).length,co=D.e.filter(e=>e.from===nd.id).length;
props.innerHTML=`<h3>${t.l}</h3><div class="field"><label>名称<input id="pv-n" value="${esc(nd.n)}"></label></div><div class="field"><label>类型<select id="pv-t">${pal.map(k=>`<option value="${k}"${k===nd.t?' selected':''}>${CT[k].l}</option>`).join('')}</select></label></div><div class="field"><label>备注<input id="pv-d" value="${esc(nd.d||'')}"></label></div><p class="cv-meta">入线 ${ci} · 出线 ${co}</p><button class="btn red" id="pv-del">删除组件</button>`;
const pn=document.getElementById('pv-n');pn.oninput=()=>{nd.n=pn.value.trim()||nd.n;const b=gN.querySelector(`.cv-node[data-id="${nd.id}"] .cv-name`);if(b){b.textContent=nd.n;b.title=nd.n}persistSoon()};
const pt=document.getElementById('pv-t');pt.onchange=()=>{snap();nd.t=pt.value;render();persistSoon()};
const pd=document.getElementById('pv-d');pd.oninput=()=>{nd.d=pd.value.trim();const el=gN.querySelector(`.cv-node[data-id="${nd.id}"]`);let nt=el.querySelector('.cv-note');if(nd.d){if(!nt){nt=document.createElement('small');nt.className='cv-note';el.appendChild(nt)}nt.textContent=nd.d}else if(nt)nt.remove();persistSoon()};
document.getElementById('pv-del').onclick=()=>delNode(nd.id);return}
const eg=D.e.find(x=>x.id===sel);
if(eg){const f=find(eg.from),t2=find(eg.to);props.innerHTML=`<h3>连线</h3><p class="cv-meta">${esc(f?f.n:'?')} → ${esc(t2?t2.n:'?')}</p><button class="btn red" id="pv-del">删除连线</button>`;document.getElementById('pv-del').onclick=()=>delEdge(eg.id);return}
props.innerHTML=`<h3>使用说明</h3><p class="cv-tip">· 点上方按钮添加组件（本页：${pal.map(k=>CT[k].l).join(' / ')}）<br>· 拖拽组件移动，自动对齐网格<br>· 悬停组件，从边缘圆点拖到另一组件完成连线<br>· 双击组件改名，或选中后在面板编辑名称/类型/备注<br>· 选中组件或连线，按 Delete 删除，Ctrl+Z 撤销<br>· 变更自动保存</p>`}
document.querySelectorAll('.cv-add').forEach(b=>b.onclick=()=>addNode(b.dataset.t));
document.getElementById('cv-clear').onclick=()=>{if(!D.n.length&&!D.e.length)return toast2('画布已为空');if(!confirm('清空当前画布？'))return;snap();D={n:[],e:[]};render();persist();toast2('已清空（Ctrl+Z 可恢复）')};
document.getElementById('cv-save').onclick=()=>{persist();toast2('已保存')};
stage.addEventListener('pointerdown',()=>{if(sel){sel=null;paintSel();renderEdges();renderProps()}});
document.addEventListener('keydown',e=>{const a=document.activeElement,tag=a?a.tagName:'';if(tag==='INPUT'||tag==='SELECT'||tag==='TEXTAREA')return;if(sel&&(e.key==='Delete'||e.key==='Backspace')){e.preventDefault();D.e.some(x=>x.id===sel)?delEdge(sel):delNode(sel)}else if((e.ctrlKey||e.metaKey)&&!e.shiftKey&&e.key.toLowerCase()==='z'){e.preventDefault();undo()}else if(e.key==='Escape'&&sel){sel=null;paintSel();renderEdges();renderProps()}});
render();
return{add:addNode,del:delNode,data:()=>clone(D)}
}
function vscene(i){const cols=['#c9d6dd','#e8d9a0','#8fd3c6','#f2c14e','#0aa68f'];const sp=[0,50,50,50,50][i];const tags=['STEP 1 / 5 装夹找正','STEP 2 / 5 参数调用','STEP 3 / 5 半精试切','STEP 4 / 5 在机测量','STEP 5 / 5 精铣确认'];return `<svg viewBox="0 0 560 300" class="vframe"><rect x="30" y="26" width="500" height="244" rx="12" fill="#0d2c3a"/><rect x="60" y="56" width="440" height="150" rx="8" fill="#123a4c"/><rect x="60" y="206" width="440" height="18" rx="4" fill="#1d566e"/><polygon points="260,${56+sp} 300,${56+sp} 280,${84+sp}" fill="#55dbc5"/><rect x="272" y="${82+sp}" width="16" height="28" fill="#9cb5c0"/><rect x="215" y="172" width="130" height="30" rx="5" fill="${cols[i]}" stroke="#eaf4f7"/>${i>=1?`<line x1="215" y1="160" x2="345" y2="160" stroke="#f39446" stroke-width="2"/><path d="M215 156 l8 4 -8 4z M345 156 l-8 4 8 4z" fill="#f39446"/><text x="248" y="152" fill="#f39446" font-size="12">X 漂移监控</text>`:''}${i===3?`<circle cx="280" cy="166" r="9" fill="none" stroke="#f2c14e" stroke-width="2"/><circle cx="280" cy="166" r="3" fill="#f2c14e"/><text x="296" y="170" fill="#f2c14e" font-size="11">机内测头</text>`:''}${i===4?`<text x="262" y="122" fill="#55dbc5" font-size="22">✓ 合格</text>`:''}<text x="42" y="258" fill="#9cb5c0" font-size="12">${tags[i]}</text><text x="474" y="262" fill="#35606f" font-size="26" font-weight="700">${i+1}</text></svg>`}
function videoCard(t){const steps=[['装夹与找正','放置毛坯，确认定位基准与夹具编号，百分表找正 ≤0.02mm。'],['调用补偿参数','读取 K-01 v3 热补偿参数，输入刀补 D05，校准工件坐标系。'],['半精铣试切','留量 0.3mm 试切，观察 X 向漂移趋势与扭矩曲线窗口。'],['在机测量','机内测头测量孔径，与首件记录比对，超差即时预警。'],['精铣与确认','执行精铣，确认尺寸窗口，提交读数并回写知识。']];window.__vid={steps};return `<div class="card vid"><div class="vid-head"><h3>AI 操作视频教学</h3><span class="badge">依据「${esc(t.name)}」· K-01 v3 · VCN-530C 手册 自动生成</span></div><div class="vid-grid"><div><div class="vid-screen" id="vid-scr"></div><div class="vid-ctl"><button class="btn" id="vid-play">▶ 播放</button><div class="vid-bar" id="vid-bar"><i id="vid-fill"></i></div><span class="vid-time" id="vid-time">00:00 / 00:30</span></div></div><ol class="vid-steps" id="vid-steps">${steps.map((s,i)=>`<li data-i="${i}"><b>${i+1}. ${s[0]}</b><small>${s[1]}</small></li>`).join('')}</ol></div></div>`}
function initVideo(){const scr=document.getElementById('vid-scr');if(!scr||!window.__vid)return;const steps=window.__vid.steps,per=6,total=steps.length*per;let curI=0,sec=0,tmr=null;const fill=document.getElementById('vid-fill'),time=document.getElementById('vid-time'),playBtn=document.getElementById('vid-play');const fmt=v=>String(Math.floor(v/60)).padStart(2,'0')+':'+String(Math.floor(v%60)).padStart(2,'0');function frame(i){curI=i;scr.innerHTML=vscene(i);document.querySelectorAll('#vid-steps li').forEach((li,k)=>li.classList.toggle('on',k===i))}function stop(){clearInterval(tmr);tmr=null;playBtn.textContent=sec>=total?'↻ 重播':'▶ 播放'}function tick(){sec+=.1;if(sec>=total){sec=total;stop()}const i=Math.min(steps.length-1,Math.floor(sec/per));if(i!==curI)frame(i);fill.style.width=(sec/total*100)+'%';time.textContent=fmt(sec)+' / '+fmt(total)}playBtn.onclick=()=>{if(tmr)return stop();if(sec>=total){sec=0;frame(0)}playBtn.textContent='⏸ 暂停';tmr=setInterval(tick,100)};document.getElementById('vid-bar').onclick=e=>{const b=e.currentTarget.getBoundingClientRect();sec=Math.max(0,Math.min(total-.01,(e.clientX-b.left)/b.width*total));frame(Math.min(steps.length-1,Math.floor(sec/per)));fill.style.width=(sec/total*100)+'%';time.textContent=fmt(sec)+' / '+fmt(total)};document.querySelectorAll('#vid-steps li').forEach(li=>li.onclick=()=>{sec=+li.dataset.i*per+.01;frame(+li.dataset.i);fill.style.width=(sec/total*100)+'%'});frame(0)}
const flowbar=()=>{const t=DB.tasks.find(x=>x.line==='L1'&&x.op==='OP30')||DB.tasks[2];return `<div class="flow"><div class="step done"><b>OP10 上料</b><small>完成 · 06m</small></div>→<div class="step done"><b>OP20 钻孔</b><small>完成 · 11m</small></div>→<div class="step current"><b>OP30 精铣</b><small>${t.status} · ${t.time}</small></div>→<div class="step locked"><b>OP40 品质</b><small>等待放行</small></div></div>`};
window.opF={st:'全部',line:'全部',op:'全部',kind:'全部'};
function kindBadge(t){return t.kind==='sos'?'<span class="badge danger">SOS</span>':t.kind==='precision'?'<span class="badge warn">精度预警</span>':t.kind==='approval'?'<span class="badge warn">待审批</span>':t.kind==='warn'?'<span class="badge dim">待分配</span>':''}
function opList(){const f=window.opF;let L=DB.tasks.filter(t=>t.who===r.alias);if(f.st!=='全部')L=L.filter(t=>t.status===f.st);if(f.line!=='全部')L=L.filter(t=>t.line===f.line);if(f.op!=='全部')L=L.filter(t=>t.op===f.op);if(f.kind!=='全部')L=L.filter(t=>t.kind===f.kind);const box=document.getElementById('op-list');if(!box)return;box.innerHTML=L.length?L.map(t=>`<div class="card trow${t.status==='未开始'?' todo':''}${t.kind==='sos'||t.status==='异常'?' alarm':''}" onclick="location='?page=detail&id=${t.id}'">${avatar(t.who||'?')}<div class="tinfo"><b>${esc(t.name)}</b><small>${lineName(t.line)} · ${t.st} · ${t.op} · ${esc(t.who||'未分配')}</small></div>${sbadge(t.status)}${kindBadge(t)}${t.status==='未开始'?`<button class="btn sm2" onclick="event.stopPropagation();acceptTask('${t.id}')">接单</button>`:''}<small class="ttime">${t.time}</small><span class="go">详情 →</span></div>`).join(''):'<div class="card empty">没有符合筛选条件的任务</div>'}
function opSet(f,v){window.opF[f]=v;if(f==='st')document.querySelectorAll('#op-tabs .chip').forEach(c=>c.classList.toggle('on',c.textContent===v));opList()}
function kUse(id){const k=DB.kn.find(x=>x.id===id);if(!k)return;k.uses++;k.views++;saveDB();audit('知识引用',k.id);toast('已引用「'+k.title+'」，使用次数 +1')}
function fbSubmit(id){audit('任务反馈提交',id);toast('结果已提交，任务轨迹已更新')}
