function acceptTask(id){const t=DB.tasks.find(x=>x.id===id);if(!t)return;t.status='作业中';saveDB();audit('任务接单',t.name);toast('已接单，开始作业');render()}
function opTodo(){const L=DB.tasks.filter(t=>t.who===r.alias&&t.status==='未开始');if(!L.length)return '';return `<div class="card todo-band"><div><b>待接单 ${L.length} 单</b><small>请尽快接单开始作业，超时将通知作业长</small></div><div class="todo-acts">${L.map(t=>`<button class="btn" onclick="acceptTask('${t.id}')">接单 · ${esc(t.name)}</button>`).join(' ')}</div></div>`}
P.operator={home:()=>{const tab=window.opTab||'总览';const tabs=['总览','我的任务','我的历史'];const mine=DB.tasks.filter(t=>t.who===r.alias);let body='';
if(tab==='总览'){const busy=mine.filter(t=>t.status==='作业中');const sos=mine.filter(t=>t.kind==='sos'||t.status==='异常');
body=opTodo()+stats([['我的工位','ST-03'],['作业中',busy.length+' 单'],['班次进度','6 / 8'],['待接单',mine.filter(t=>t.status==='未开始').length+' 单']])+flowbar()+(sos.length?`<h3 class="sect alarm-h">异常与 SOS</h3>`+sos.map(t=>`<div class="card trow alarm" onclick="location='?page=detail&id=${t.id}'">${avatar(t.who)}<div class="tinfo"><b>${esc(t.name)}</b><small>${t.st} · ${t.op} · ${esc(t.next)}</small></div>${sbadge(t.status)}${kindBadge(t)}<span class="go">处理 →</span></div>`).join(''):'')+(busy.length?`<h3 class="sect">进行中作业（${busy.length}）</h3>`+busy.map(t=>`<div class="card trow" onclick="location='?page=detail&id=${t.id}'">${avatar(t.who)}<div class="tinfo"><b>${esc(t.name)}</b><small>${t.st} · ${t.op} · 停留 ${t.time}</small></div>${sbadge(t.status)}<span class="go">详情 →</span></div>`).join(''):'')+`<h3 class="sect">我的工位推荐知识</h3><div class="grid3">${DB.kn.filter(k=>k.stat==='启用'&&k.ops.split(',').some(o=>['OP10','OP20','OP30'].includes(o))).slice(0,3).map(k=>`<div class="card"><div class="doc-h"><b>${esc(k.title)}</b><span class="badge">${esc(k.type)}</span></div><p class="dim">v${k.versions[0].v} · 正确率 ${k.acc}%</p><button class="btn ghost sm2" onclick="kUse('${k.id}')">引用</button></div>`).join('')}</div>`}
if(tab==='我的任务')body=`<div class="card"><div class="chips" id="op-tabs">${['全部','未开始','作业中','完成','异常'].map(s=>`<button class="chip${window.opF.st===s?' on':''}" onclick="opSet('st','${s}')">${s}</button>`).join('')}</div><div class="filters"><label>异常类型<select onchange="opSet('kind',this.value)"><option value="全部">全部</option><option value="sos">SOS</option><option value="precision">精度预警</option><option value="approval">待审批</option><option value="warn">待分配</option></select></label><label>产线<select onchange="opSet('line',this.value)"><option value="全部">全部</option><option value="L1">Line A</option><option value="L2">Line B</option></select></label><label>工序<select onchange="opSet('op',this.value)"><option value="全部">全部</option>${['OP10','OP20','OP30','OP40'].map(o=>`<option>${o}</option>`).join('')}</select></label></div></div><div id="op-list"></div>`;
if(tab==='我的历史')body=table(['工位','任务','用时','状态','下一步'],mine.map(t=>`<tr><td>${t.st} · ${t.op}</td><td onclick="location='?page=detail&id=${t.id}'" class="link">${esc(t.name)}</td><td>${t.time}</td><td>${sbadge(t.status)}</td><td>${esc(t.next)}</td></tr>`));
return head('我的工作台','班次、任务与历史一站式处理。','<button class="btn red" onclick="toast(\'SOS 已发出，作业长已收到\')">SOS 求助</button>')+`<div class="chips" id="op-tabbar">${tabs.map(t=>`<button class="chip${tab===t?' on':''}" onclick="opGo('${t}')">${t}</button>`).join('')}</div>`+body},
tasks:()=>head('我的任务','按状态、异常类型、产线、工序筛选。')+`<div class="card"><div class="chips" id="op-tabs">${['全部','未开始','作业中','完成','异常'].map(s=>`<button class="chip${window.opF.st===s?' on':''}" onclick="opSet('st','${s}')">${s}</button>`).join('')}</div><div class="filters"><label>异常类型<select onchange="opSet('kind',this.value)"><option value="全部">全部</option><option value="sos">SOS</option><option value="precision">精度预警</option><option value="approval">待审批</option><option value="warn">待分配</option></select></label><label>产线<select onchange="opSet('line',this.value)"><option value="全部">全部</option><option value="L1">Line A</option><option value="L2">Line B</option></select></label><label>工序<select onchange="opSet('op',this.value)"><option value="全部">全部</option>${['OP10','OP20','OP30','OP40'].map(o=>`<option>${o}</option>`).join('')}</select></label></div></div><div id="op-list"></div>`,
knowledge:()=>head('经验与资料','已审核且匹配当前工位与工序的知识，可在线引用。')+`<div class="grid2">${DB.kn.filter(k=>k.stat==='启用').map(k=>`<div class="card"><div class="doc-h"><b>${esc(k.title)}</b><span class="badge">${esc(k.type)}</span></div><p class="dim">v${k.versions[0].v} · ${esc(k.origin)} · 适用 ${k.ops} · 被引用 ${k.uses} 次</p><div class="doc-a"><span class="badge ${k.acc>=90?'':'warn'}">正确率 ${k.acc}%</span><button class="btn ghost sm2" onclick="kUse('${k.id}')">引用</button></div></div>`).join('')}</div>`,
history:()=>head('我的历史','开始、暂停、恢复、完成与用时。')+table(['工位','任务','用时','状态','下一步'],DB.tasks.filter(t=>t.who===r.alias).map(t=>`<tr><td>${t.st} · ${t.op}</td><td onclick="location='?page=detail&id=${t.id}'" class="link">${esc(t.name)}</td><td>${t.time}</td><td>${sbadge(t.status)}</td><td>${esc(t.next)}</td></tr>`))};
window.ld={line:'L1',filter:'全部',st:null};
function fmatch(f,t){if(f==='全部')return true;if(f==='空闲')return !t;if(f==='SOS')return t&&t.kind==='sos';if(f==='待分配')return t&&!t.who&&t.status!=='完成';if(f==='异常')return t&&t.status==='异常';return t&&t.status===f}
function floorMap(){const ld=window.ld;const sts=Object.keys(STPOS[ld.line]||{});const ts=DB.tasks.filter(t=>t.line===ld.line);return `<div class="factory tall">${sts.map(st=>{const t=ts.find(x=>x.st===st&&x.status!=='完成')||ts.find(x=>x.st===st);const stat=t?(t.kind==='sos'?'SOS':t.status):'空闲';const dim=fmatch(ld.filter,t)?'':' dim';const p=t&&t.who?DB.people.find(x=>x.n===t.who):null;const col={'完成':'#55dbc5','作业中':'#f2c14e','异常':'#e4525a','未开始':'#9cb5c0','空闲':'#54707d','SOS':'#e4525a'}[stat];return `<div class="fnode${dim}${window.ld.st===st?' sel':''}" style="left:${STPOS[ld.line][st][0]}%;top:${STPOS[ld.line][st][1]}%;--c:${col}" onclick="ldPick('${st}')"><b>${st}</b><small>${t?esc(t.name):'空闲'}</small><span class="fbadge" style="--c:${col}">${stat}</span>${p?`<i class="pdot" title="${esc(p.n)} 在位">${esc(p.n.slice(-2))}</i>`:''}</div>`}).join('')}</div>`}
function ldSide(){const ld=window.ld;const ts=DB.tasks.filter(t=>t.line===ld.line&&(ld.st?t.st===ld.st:fmatch(ld.filter,t)));return `<div class="card sidecard"><h3>${ld.st?esc(ld.st)+' 工位':'任务列表'}<small class="dim"> ${ld.filter}</small></h3>${ts.length?ts.map(t=>`<div class="trow sm" onclick="location='?page=detail&id=${t.id}'"><div class="tinfo"><b>${esc(t.name)}</b><small>${t.st} · ${t.op} · ${esc(t.who||'未分配')}</small></div>${sbadge(t.status)}</div>`).join(''):'<p class="dim">暂无匹配任务</p>'}<div class="gap"></div>${ld.st?`<button class="btn ghost sm2" onclick="ldPick(null)">显示全产线</button>`:''}<button class="btn sm2" onclick="taskForm('')">＋新建任务</button></div>`}
function ldRefresh(){const m=document.getElementById('ld-map'),s=document.getElementById('ld-side');if(m)m.innerHTML=floorMap();if(s)s.innerHTML=ldSide()}
function ldSet(k,v){window.ld[k]=v;ldRefresh()}
function ldPick(st){window.ld.st=st;ldRefresh()}
