function ldChartDraw(){const n=(window.ldRange||'7天')==='7天'?7:30;const L=D30.slice(-n);const el=document.getElementById('ld-chart');if(!el)return;el.innerHTML=lineChart(L,[{n:'作业中',c:'#f2c14e',data:LTR.busy.slice(-n)},{n:'待接单',c:'#1f7ec2',data:LTR.idle.slice(-n)},{n:'异常',c:'#e4525a',data:LTR.exc.slice(-n)},{n:'一次合格率%',c:'#0aa68f',data:LTR.acc.slice(-n)}],170);document.querySelectorAll('#ld-r .chip').forEach(c=>c.classList.toggle('on',c.textContent.indexOf(window.ldRange||'7天')>-1))}
function permPanel(){const ps=DB.people.filter(p=>p.dept==='D1');return table(['姓名','角色','技能等级','工位授权','在线'],ps.map(p=>`<tr><td>${avatar(p.n)} ${esc(p.n)}</td><td>${ROLENAME[p.role]}</td><td><select class="insel" onchange="permSet('${p.id}','skills',this.value)">${['CNC L1','CNC L2','QA L1','QA L2','装配 L1','检测 L2'].map(sk=>`<option${p.skills===sk?' selected':''}>${sk}</option>`).join('')}</select></td><td><select class="insel" onchange="permSet('${p.id}','st',this.value)">${['ST-01','ST-01,ST-02','ST-02,ST-03','ST-03,ST-04','ST-04,ST-05'].map(st=>`<option${p.st===st?' selected':''}>${st}</option>`).join('')}</select></td><td>${p.on?'<span class="badge">在线</span>':'<span class="badge dim">离线</span>'}</td></tr>`))+`<p class="dim">人员新增与删除由 Master 在「组织权限」统一管理；此处仅可调整本部门人员的技能与工位授权，变更实时生效于派工与审批匹配。</p>`}
