function tskTab(v){window.tskF.tab=v;document.querySelectorAll('#tsk-tabs .chip').forEach(c=>c.classList.toggle('on',c.textContent===(v==='list'?'任务列表':'人员与权限')));tskList()}
function permSet(pid,f,v){const p=DB.people.find(x=>x.id===pid);if(!p)return;p[f]=v;saveDB();audit('权限变更',p.n+' · '+(f==='skills'?'技能':'工位授权'));toast('已更新 '+p.n+' 的权限')}
function taskForm(id){const t=id?DB.tasks.find(x=>x.id===id):null;const ps=DB.people.filter(p=>p.dept==='D1'&&p.role==='operator');modal(`<h3>${t?'编辑任务':'新建任务'}</h3><div class="field"><label>任务名称<input id="tf-name" value="${t?esc(t.name):''}" placeholder="如：E-401 平面精铣"></label></div><div class="grid2"><div class="field"><label>流水线<select id="tf-line">${['L1','L2'].map(l=>`<option value="${l}"${t&&t.line===l?' selected':''}>${lineName(l)}</option>`).join('')}</select></label></div><div class="field"><label>工位<select id="tf-st">${['ST-01','ST-02','ST-03','ST-04','ST-05','ST-06'].map(s=>`<option${t&&t.st===s?' selected':''}>${s}</option>`).join('')}</select></label></div></div><div class="grid2"><div class="field"><label>工序<select id="tf-op">${['OP10','OP20','OP30','OP40'].map(o=>`<option${t&&t.op===o?' selected':''}>${o}</option>`).join('')}</select></label></div><div class="field"><label>类型<select id="tf-kind"><option value=""${t&&!t.kind?' selected':''}>常规</option><option value="approval"${t&&t.kind==='approval'?' selected':''}>首件/待审批</option><option value="precision"${t&&t.kind==='precision'?' selected':''}>精度预警</option><option value="sos"${t&&t.kind==='sos'?' selected':''}>SOS</option><option value="warn"${t&&t.kind==='warn'?' selected':''}>待分配</option></select></label></div></div><div class="field"><label>负责人<select id="tf-who"><option value="">未分配</option>${ps.map(p=>`<option${t&&t.who===p.n?' selected':''}>${esc(p.n)}</option>`).join('')}</select></label></div><div class="field"><label>任务说明<textarea id="tf-desc">${t?esc(t.desc):''}</textarea></label></div><div class="macts"><button class="btn" onclick="taskSave('${id||''}')">保存</button><button class="btn ghost" onclick="closeModal()">取消</button></div>`)}
function taskSave(id){const g=x=>document.getElementById(x).value;const name=g('tf-name').trim();if(!name)return toast('请填写任务名称');const data={name,line:g('tf-line'),st:g('tf-st'),op:g('tf-op'),kind:g('tf-kind'),who:g('tf-who'),desc:g('tf-desc')||'无补充说明。'};if(id){Object.assign(DB.tasks.find(x=>x.id===id),data);audit('任务更新',name)}else{DB.tasks.unshift({id:'T-'+Date.now()%10000,...data,time:'--',status:'未开始',next:'待开始'});audit('任务创建',name)}saveDB();closeModal();toast('任务已保存');render()}
function taskDel(id){const t=DB.tasks.find(x=>x.id===id);if(!t)return;if(!confirm('删除任务「'+t.name+'」？'))return;DB.tasks=DB.tasks.filter(x=>x.id!==id);saveDB();audit('任务删除',t.name);toast('任务已删除');render()}
function taskAssign(id){const t=DB.tasks.find(x=>x.id===id);if(!t)return;const ps=DB.people.filter(p=>p.dept==='D1'&&p.role==='operator');const load={};deptTasks().forEach(x=>{if(x.who)load[x.who]=(load[x.who]||0)+1});modal(`<h3>分配任务 · ${esc(t.name)}</h3><p class="dim">${t.st} · ${t.op} · ${lineName(t.line)}</p>${ps.map(p=>`<label class="pick"><input type="radio" name="asg" value="${esc(p.n)}"${t.who===p.n?' checked':''}> ${avatar(p.n)} <b>${esc(p.n)}</b><small>　${esc(p.skills)} · ${p.st} · 当前负荷 ${load[p.n]||0} 单</small></label>`).join('')}<div class="macts"><button class="btn" onclick="assignSave('${id}')">确认分配</button><button class="btn ghost" onclick="closeModal()">取消</button></div>`)}
function assignSave(id){const c=document.querySelector('input[name="asg"]:checked');if(!c)return toast('请选择人员');const t=DB.tasks.find(x=>x.id===id);t.who=c.value;if(t.status==='异常')t.status='未开始';saveDB();audit('任务分配',t.name+' → '+t.who);closeModal();toast('已分配给 '+t.who);render()}
function apprList(){return DB.tasks.filter(t=>(t.kind==='approval'||t.kind==='sos'||t.kind==='precision')&&t.status!=='完成')}
function apprDo(id,ok){const t=DB.tasks.find(x=>x.id===id);if(!t)return;t.status=ok?'完成':'异常';if(ok)t.kind='';saveDB();audit(ok?'审批通过':'审批驳回',t.name);toast(ok?'已放行 · '+t.name:'已驳回，转入异常处理');render()}
function escal(id){const t=DB.tasks.find(x=>x.id===id);if(!t)return;audit('SOS 升级',t.name);toast('已按策略升级：作业长 → 专家 → Master');render()}
function knPush(id){const k=DB.kn.find(x=>x.id===id);modal(`<h3>推送到工位</h3><p class="dim">${esc(k.title)} · v${k.versions[0].v} · 正确率 ${k.acc}%</p><div class="field"><label>目标工位<select id="kp-st">${['ST-01','ST-02','ST-03','ST-04','ST-05','ST-06'].map(s=>`<option>${s}</option>`).join('')}</select></label></div><div class="macts"><button class="btn" onclick="knPushDo('${id}')">确认推送</button><button class="btn ghost" onclick="closeModal()">取消</button></div>`)}
function knPushDo(id){const k=DB.kn.find(x=>x.id===id);const st=document.getElementById('kp-st').value;k.uses++;if(!k.depts.split(',').includes('D1'))k.depts=k.depts?k.depts+',D1':'D1';saveDB();audit('知识推送',k.id+' → '+st);closeModal();toast('已推送到 '+st+'，现场将优先匹配该知识');render()}
P.leader={home:()=>{const ts=deptTasks();const tab=window.ldTab2||'任务管理';
const chart=`<div class="card"><div class="ld-head"><h3>产线趋势（点击数据点看当日详情）</h3><div class="chips" style="margin:0" id="ld-r"><button class="chip${(window.ldRange||'7天')==='7天'?' on':''}" onclick="ldRangeSet('7天')">近 7 天</button><button class="chip${(window.ldRange||'7天')==='30天'?' on':''}" onclick="ldRangeSet('30天')">近 30 天</button></div></div><div id="ld-chart"></div></div>`;
const right=`<div class="card ld-right"><h3>当前状态</h3>${[['在岗',DB.people.filter(p=>p.dept==='D1'&&p.on).length+' 人'],['作业中',ts.filter(t=>t.status==='作业中').length+' 单'],['异常/SOS',ts.filter(t=>t.status==='异常'||t.kind==='sos').length+' 单'],['待分配',ts.filter(t=>!t.who&&t.status!=='完成').length+' 单']].map(x=>`<div class="krow"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div>`;
const body=tab==='任务管理'?`<div class="tabbar"><button class="btn" onclick="taskForm('')">＋新建任务</button></div><div id="tsk-box"></div>`:tab==='审批中心'?table(['任务','触发','审批链（绑定组织）','时限','操作'],apprList().map(t=>{const a=DB.ap.find(x=>x.id===(t.kind==='sos'?'A3':'A1'));return `<tr><td onclick="location='?page=detail&id=${t.id}'" class="link">${esc(t.name)}</td><td>${esc(t.desc.slice(0,16))}…</td><td>${a.chain.map(s=>deptName(s.dept)+'·'+ROLENAME[s.role].split('/')[0]).join(' → ')}</td><td>${a.sla}</td><td class="acts"><button class="btn sm2" onclick="apprDo('${t.id}',true)">通过</button><button class="btn red sm2" onclick="apprDo('${t.id}',false)">驳回</button><button class="btn ghost sm2" onclick="escal('${t.id}')">升级</button></td></tr>`})):table(['工位','任务','负责人','状态','下一步','操作'],deptTasks().filter(t=>t.kind==='sos'||t.status==='异常'||t.kind==='warn').map(t=>`<tr><td>${t.st} · ${t.op}</td><td onclick="location='?page=detail&id=${t.id}'" class="link">${esc(t.name)}</td><td>${esc(t.who||'未分配')}</td><td>${sbadge(t.status)}${kindBadge(t)}</td><td>${esc(t.next)}</td><td class="acts">${t.who?'':'<button class="btn ghost sm2" onclick="taskAssign(\''+t.id+'\')">分配</button>'}<button class="btn ghost sm2" onclick="escal('${t.id}')">升级</button></td></tr>`));
return head('产线工作台','趋势图表、现场布局与任务处理一体化。')+`<div class="ld-top">${chart}${right}</div>`+`<div class="card"><h3>现场布局</h3><div class="filters"><label>产线<select onchange="ldSet('line',this.value);ldSet('filter','全部')"><option value="L1">Line A</option><option value="L2">Line B</option></select></label></div><div class="chips" id="ld-chips">${['全部','未开始','作业中','异常','SOS','待分配'].map(s=>`<button class="chip${window.ld.filter===s?' on':''}" onclick="ldFilter('${s}')">${s}</button>`).join('')}</div><div class="floor-wrap"><div id="ld-map">${floorMap()}</div><div id="ld-side">${ldSide()}</div></div></div>`+`<div class="chips" id="ld-tabs2">${['任务管理','审批中心','异常与SOS'].map(t=>`<button class="chip${tab===t?' on':''}" onclick="ldGo2('${t}')">${t}</button>`).join('')}</div>`+body},
perm:()=>head('人员管理','管理本部门人员的技能等级与工位授权（新增删除由 Master 统一管理）。')+'<div id="perm-box"></div>',
flow:()=>q.get('doc')?docEditorPage('flow'):docList('flow'),
knowledge:()=>head('知识管理','本部门在用知识：推送到工位、查看版本、沉淀新经验。','<button class="btn" onclick="knNew()">＋沉淀新知识</button>')+table(['知识','类型/版本','适用工序','正确率','引用','操作'],DB.kn.filter(k=>k.stat!=='废弃').map(k=>`<tr><td>${esc(k.title)}</td><td>${esc(k.type)} · v${k.versions[0].v}</td><td>${k.ops}</td><td>${k.acc}%</td><td>${k.depts.split(',').includes('D1')?'<span class="badge">在用</span> ':''}${k.uses} 次</td><td class="acts"><button class="btn ghost sm2" onclick="knPush('${k.id}')">推送工位</button><button class="btn ghost sm2" onclick="knVersions('${k.id}',true)">版本</button></td></tr>`)),
approval:()=>head('审批中心','审批链与审批策略按组织权限自动匹配。')+table(['任务','触发','审批链（绑定组织）','时限','操作'],apprList().map(t=>{const a=DB.ap.find(x=>x.id===(t.kind==='sos'?'A3':'A1'));return `<tr><td onclick="location='?page=detail&id=${t.id}'" class="link">${esc(t.name)}</td><td>${esc(t.desc.slice(0,16))}…</td><td>${a.chain.map(s=>deptName(s.dept)+'·'+ROLENAME[s.role].split('/')[0]).join(' → ')}</td><td>${a.sla}</td><td class="acts"><button class="btn sm2" onclick="apprDo('${t.id}',true)">通过</button><button class="btn red sm2" onclick="apprDo('${t.id}',false)">驳回</button><button class="btn ghost sm2" onclick="escal('${t.id}')">升级</button></td></tr>`})),
exceptions:()=>head('异常与SOS','超时、停线、升级和待分配任务。')+table(['工位','任务','负责人','状态','下一步','操作'],deptTasks().filter(t=>t.kind==='sos'||t.status==='异常'||t.kind==='warn').map(t=>`<tr><td>${t.st} · ${t.op}</td><td onclick="location='?page=detail&id=${t.id}'" class="link">${esc(t.name)}</td><td>${esc(t.who||'未分配')}</td><td>${sbadge(t.status)}${kindBadge(t)}</td><td>${esc(t.next)}</td><td class="acts">${t.who?'':'<button class="btn ghost sm2" onclick="taskAssign(\''+t.id+'\')">分配</button>'}<button class="btn ghost sm2" onclick="escal('${t.id}')">升级</button></td></tr>`))};
function knVersions(id,ro){const k=DB.kn.find(x=>x.id===id);modal(`<h3>版本管理 · ${esc(k.title)}</h3><table class="table"><tr><th>版本</th><th>日期</th><th>修订人</th><th>说明</th></tr>${k.versions.map(v=>`<tr><td><b>v${v.v}</b></td><td>${v.d}</td><td>${esc(v.by)}</td><td>${esc(v.note)}</td></tr>`).join('')}</table>${ro?'':`<div class="field"><label>新版本说明<input id="kv-note" placeholder="本次修订内容"></label></div><div class="macts"><button class="btn" onclick="knVerAdd('${id}')">发布新版本（替换当前）</button><button class="btn ghost" onclick="closeModal()">取消</button></div>`}`)}
function knVerAdd(id){const k=DB.kn.find(x=>x.id===id);const note=document.getElementById('kv-note').value.trim()||'内容修订';const nv=k.versions[0].v+1;k.versions.unshift({v:nv,d:today(),by:cur().alias,note});if(k.stat==='废弃')k.stat='审核中';saveDB();audit('版本更新',k.id+' v'+nv);closeModal();toast('已发布 v'+nv+'，进入审核流程');render()}
function knNew(){modal(`<h3>新建知识</h3><div class="field"><label>标题<input id="kn-title" placeholder="如：薄壁件变形控制"></label></div><div class="grid2"><div class="field"><label>类型<select id="kn-type"><option>经验</option><option>SOP</option><option>手册</option><option>视频</option><option>CASE</option></select></label></div><div class="field"><label>适用工序<select id="kn-ops"><option>OP10</option><option>OP20</option><option>OP30</option><option>OP40</option></select></label></div></div><div class="field"><label>内容摘要<textarea id="kn-body" placeholder="关键要点、参数、注意事项…"></textarea></label></div><div class="macts"><button class="btn" onclick="knSave()">提交</button><button class="btn ghost" onclick="closeModal()">取消</button></div>`)}
function knSave(){const t=document.getElementById('kn-title').value.trim();if(!t)return toast('请填写标题');const me=cur();const id='K-'+Date.now()%10000;DB.kn.unshift({id,title:t,type:document.getElementById('kn-type').value,dept:me.dept,origin:me.alias,ops:document.getElementById('kn-ops').value,versions:[{v:1,d:today(),by:me.alias,note:'初版'}],views:0,uses:0,depts:'',acc:0,stat:'审核中',src:role==='expert'?'专家沉淀':role==='leader'?'现场沉淀':'治理创建'});saveDB();audit('知识发布',id+' '+t);closeModal();toast('已提交，进入审核流程');render()}
function knStat(id,s){const k=DB.kn.find(x=>x.id===id);if(!k)return;k.stat=s;saveDB();audit(s==='启用'?'知识恢复':'知识废弃',k.id+' '+k.title);toast('「'+k.title+'」已标记为 '+s);render()}
function knDel(id){const k=DB.kn.find(x=>x.id===id);if(!k)return;if(!confirm('彻底删除「'+k.title+'」？该操作会记入审计。'))return;DB.kn=DB.kn.filter(x=>x.id!==id);saveDB();audit('知识删除',k.id+' '+k.title);toast('知识已删除');render()}
function knApprove(id,ok){const k=DB.kn.find(x=>x.id===id);if(!k)return;k.stat=ok?'启用':'废弃';saveDB();audit(ok?'知识审核通过':'知识驳回',k.id+' '+k.title);toast(ok?'「'+k.title+'」已发布启用':'「'+k.title+'」已驳回');render()}
function docList(type){const isM=role==='master';const docs=DB.docs.filter(d=>d.type===type&&(isM?d.stat!=='产线实例':d.stat==='已发布'||d.stat==='草稿'));const inst=DB.docs.filter(d=>d.type==='flow'&&d.stat==='产线实例');const label=type==='layout'?'布局':'模板';return head(type==='layout'?'布局中心':'模板中心',type==='layout'?'工厂、产线、工位与设备布局的全生命周期管理。':'标准工序流程模板，支持版本化与产线下发。',`<button class="btn" onclick="docNew('${type}')">＋新建${label}</button>`)+`<div class="docgrid">${docs.map(d=>{let has=false;try{has=!!localStorage.getItem('cv.doc.'+d.id)}catch(e){}return `<div class="card doc"><div class="doc-h"><b>${esc(d.name)}</b>${sbadge(d.stat)}</div><small class="dim">${d.id} · v${d.v} · ${d.date} · ${esc(d.by)}${has?' · 已绘制':''}</small><div class="doc-a"><button class="btn ghost sm2" onclick="location='?page=${type}&doc=${d.id}'">编辑画布</button><button class="btn ghost sm2" onclick="previewDoc('${d.id}')">预览</button>${type==='flow'&&!isM?`<button class="btn sm2" onclick="flowCopy('${d.id}')">复制为产线实例</button>`:''}<button class="btn red sm2" onclick="docDel('${d.id}')">删除</button></div></div>`}).join('')}</div>`+(type==='flow'&&!isM?`<h3 class="sect">本产线实例</h3><div class="docgrid">${inst.length?inst.map(d=>`<div class="card doc"><div class="doc-h"><b>${esc(d.name)}</b>${sbadge(d.stat)}</div><small class="dim">${d.id} · v${d.v} · ${d.date} · ${esc(d.by)}</small><div class="doc-a"><button class="btn ghost sm2" onclick="location='?page=flow&doc=${d.id}'">编辑画布</button><button class="btn red sm2" onclick="docDel('${d.id}')">删除</button></div></div>`).join(''):'<p class="dim">尚无实例，可从上方标准模板「复制为产线实例」后独立编辑。</p>'}</div>`:'')}
function previewDoc(id){const d=DB.docs.find(x=>x.id===id);let data=null;try{data=JSON.parse(localStorage.getItem('cv.doc.'+id))}catch(e){}const nodes=data&&data.n&&data.n.length?data.n:(CSEED[d.type]||CSEED.flow).n;const edgs=data&&data.e&&data.e.length?data.e:(CSEED[d.type]||CSEED.flow).e;const pos={};nodes.forEach(n=>pos[n.id]=[30+n.x*.42+36,16+n.y*.42+13]);const lines=edgs.map(e=>{const a=pos[e.from],b=pos[e.to];return a&&b?`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}"/>`:''}).join('');modal(`<h3>预览 · ${esc(d.name)}</h3><div class="mini-cv"><svg class="medges"><defs><marker id="marr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#5b7684"/></marker></defs>${lines}</svg>${nodes.map(n=>{const t=CT[n.t]||CT.op;return `<span class="mnode" style="--c:${t.c};left:${30+n.x*.42}px;top:${16+n.y*.42}px;${t.s==='diamond'?'transform:rotate(45deg);':''}${t.s==='pill'?'border-radius:999px;':''}">${t.s==='diamond'?`<i>${esc(n.n)}</i>`:esc(n.n)}</span>`}).join('')}</div><p class="dim">共 ${nodes.length} 个节点 · ${d.stat} · v${d.v} · ${d.date}</p><div class="macts"><button class="btn" onclick="closeModal();location='?page=${d.type}&doc=${d.id}'">打开编辑器</button><button class="btn ghost" onclick="closeModal()">关闭</button></div>`)}
function docNew(type){modal(`<h3>新建${type==='layout'?'工厂布局':'流程模板'}</h3><div class="field"><label>名称<input id="dn-name" placeholder="如：大连一厂 Line B 布局"></label></div><div class="macts"><button class="btn" onclick="docSave('${type}')">创建并编辑</button><button class="btn ghost" onclick="closeModal()">取消</button></div>`)}
function docSave(type){const n=document.getElementById('dn-name').value.trim();if(!n)return toast('请填写名称');const id=(type==='layout'?'LA-':'FL-')+Date.now()%10000;DB.docs.unshift({id,type,name:n,v:1,by:cur().alias,date:today(),stat:'草稿'});saveDB();audit(type==='layout'?'布局创建':'模板创建',n);closeModal();location='?page='+type+'&doc='+id}
function docDel(id){const d=DB.docs.find(x=>x.id===id);if(!d)return;if(!confirm('删除「'+d.name+'」？'))return;DB.docs=DB.docs.filter(x=>x.id!==id);try{localStorage.removeItem('cv.doc.'+id)}catch(e){}saveDB();audit('文档删除',d.name);toast('已删除');render()}
function publishDoc(id){const docId=id||q.get('doc');const doc=DB.docs.find(x=>x.id===docId);if(!doc)return;doc.stat='已发布';doc.date=today();saveDB();audit(doc.type==='layout'?'布局发布':'模板发布',doc.name+' v'+doc.v);toast('已发布 v'+doc.v)}
function flowCopy(id){const src=DB.docs.find(x=>x.id===id);const nid='FI-'+Date.now()%10000;let data=null;try{data=localStorage.getItem('cv.doc.'+id)}catch(e){}if(data){try{localStorage.setItem('cv.doc.'+nid,data)}catch(e){}}DB.docs.unshift({id:nid,type:'flow',name:src.name+' · Line A 实例',v:1,by:cur().alias,date:today(),stat:'产线实例'});let cd=null;try{cd=JSON.parse(localStorage.getItem('cv.doc.'+nid))}catch(e){}if(!cd||!cd.n){cd=JSON.parse(JSON.stringify(CSEED.flow));try{localStorage.setItem('cv.doc.'+nid,JSON.stringify(cd))}catch(e){}}if(cd&&cd.n){cd.n.forEach(n=>{if(n.t==='op'){const code=(n.n||'').split(' ')[0];const tk=DB.tasks.find(x=>x.op===code&&x.who);if(tk)n.a=tk.who}});try{localStorage.setItem('cv.doc.'+nid,JSON.stringify(cd))}catch(e){}}saveDB();audit('实例创建',src.name);toast('已复制为产线实例，工序已匹配操作员头像');render()}
function conReply(id){const ta=document.getElementById('cr-'+id);if(!ta)return;const v=ta.value.trim();if(!v)return toast('请输入会诊意见');const c=DB.consults.find(x=>x.id===id);c.log.push({t:new Date().toISOString().slice(5,16).replace('T',' '),who:cur().alias,msg:v});if(c.stat==='待响应')c.stat='进行中';saveDB();audit('会诊回复',c.id+' '+c.problem);toast('回复已同步给 '+c.fac);render()}
function conSolve(id){const c=DB.consults.find(x=>x.id===id);c.stat='已解决';if(!c.solved)c.solved={case:'待沉淀',reuse:0,acc:0};saveDB();audit('会诊解决',c.id+' '+c.problem);toast('已标记解决，建议沉淀为知识形成复用');render()}
function conSink(id){const c=DB.consults.find(x=>x.id===id);knNew();setTimeout(()=>{const t=document.getElementById('kn-title');if(t){t.value='CASE · '+c.problem;document.getElementById('kn-body').value='来源：'+c.fac+' '+c.line+' 会诊 '+c.id+'。关键证据：'+c.ev+'。结论：见会诊记录。'}},0)}
function histReuse(id){const c=DB.consults.find(x=>x.id===id);if(c.solved&&c.solved.case!=='待沉淀'){c.solved.reuse++;saveDB();audit('经验复用',c.solved.case);toast('已复用 '+c.solved.case+'，累计 '+c.solved.reuse+' 次');render()}else toast('请先沉淀为知识')}
window.conF=window.conF||'全部';
function conCard(c){return `<div class="card trow${c.stat==='待响应'?' alarm':''}" onclick="location='?page=consult&id=${c.id}'">${avatar(c.expert)}<div class="tinfo"><b>${esc(c.problem)}</b><small>${c.fac} · ${c.line} · 证据：${esc(c.ev)} · ${c.log.length} 条处理记录</small></div>${sbadge(c.stat)}<span class="go">进入会诊 →</span></div>`}
function conSet(v){window.conF=v;render()}
P.expert={home:()=>{const all=DB.consults;const cs=all.filter(c=>window.conF==='全部'||c.stat===window.conF);return head('会诊工作台','跨厂会诊一览，点击进入单个会诊的完整详细页。')+stats([['待处理',all.filter(c=>c.stat!=='已解决').length],['待响应',all.filter(c=>c.stat==='待响应').length],['进行中',all.filter(c=>c.stat==='进行中').length],['本月已解决',all.filter(c=>c.stat==='已解决').length]])+chips(window.conF,['全部','待响应','进行中','已解决'],'conSet')+(cs.map(conCard).join('')||'<div class="card empty">没有符合条件的会诊</div>')},
consult:()=>{const c=DB.consults.find(x=>x.id===q.get('id'));if(!c)return head('会诊不存在','请从会诊工作台进入。',`<a class="btn ghost" href="?page=home">← 返回一览</a>`);const kns=(c.kns||'').split(',').filter(Boolean).map(id=>DB.kn.find(k=>k.id===id)).filter(Boolean);return head((c.stat==='已解决'?'会诊复盘':'会诊详情')+' · '+esc(c.problem),c.fac+' · '+c.line+' · 专家 '+esc(c.expert),`<a class="btn ghost" href="?page=home">← 返回一览</a>`+(c.taskId?`<button class="btn" onclick="location='?page=detail&id=${c.taskId}'">查看关联现场任务 ${c.taskId}</button>`:''))+`<div class="detail"><div class="card"><h3>问题描述</h3><p>${esc(c.log[0]?c.log[0].msg:'现场上报问题。')}</p><h3>当前证据</h3><div class="chips">${c.ev.split(',').map(e=>`<span class="chip static">${esc(e)}</span>`).join('')}</div><h3>当前可能问题（AI 诊断）</h3>${(c.hypo||'待分析').split('/').map(h=>`<p><span class="badge warn">${esc(h.trim())}</span></p>`).join('')}<h3>使用的经验 / 手册 / 视频</h3>${kns.map(k=>`<div class="trow sm"><div class="tinfo"><b>${esc(k.title)}</b><small>v${k.versions[0].v} · 正确率 ${k.acc}% · ${esc(k.type)}</small></div><button class="btn ghost sm2" onclick="kUse('${k.id}')">引用</button></div>`).join('')||'<p class="dim">暂无</p>'}${c.vids?`<p class="dim">已观看视频：${esc(c.vids)}</p>`:''}<h3>处理轨迹（每次处理详细）</h3><div class="timeline">${c.log.map(l=>`<p><b>${esc(l.who)}</b> <small class="dim">${l.t}</small><br>${esc(l.msg)}</p>`).join('')}</div>${c.stat!=='已解决'?`<div class="field"><label>会诊回复<textarea id="cr-${c.id}" placeholder="给出判定、参数建议或请求补充证据…"></textarea></label><div class="toolbar"><button class="btn" onclick="conReply('${c.id}')">回复</button><button class="btn ghost" onclick="conSolve('${c.id}')">标记解决</button><button class="btn ghost" onclick="conSink('${c.id}')">沉淀为知识</button></div></div>`:`<div class="doc-a"><span class="badge">沉淀 ${esc(c.solved.case)} · 被复用 ${c.solved.reuse} 次 · 采纳率 ${c.solved.acc}%</span><button class="btn ghost sm2" onclick="histReuse('${c.id}')">推广复用 +1</button></div>`}</div><aside class="card"><h3>会诊信息</h3><p><b>工厂：</b>${c.fac}</p><p><b>产线：</b>${c.line}</p><p><b>状态：</b>${sbadge(c.stat)}</p><h3>关联现场</h3>${c.taskId?`<p><span class="link" onclick="location='?page=detail&id=${c.taskId}'" style="cursor:pointer">${c.taskId} 任务详情 →</span></p>`:'<p class="dim">暂无关联任务</p>'}<h3>引用知识</h3><p class="dim">${kns.length?kns.map(k=>k.id+' '+k.title).join('；'):'--'}</p></aside></div>`},
knowledge:()=>head('经验沉淀','把会诊结论与个人经验沉淀为组织知识，进入版本管理。','<button class="btn" onclick="knNew()">＋新建经验</button>')+table(['知识','类型/版本','适用工序','使用','状态','操作'],DB.kn.filter(k=>k.origin===r.alias||k.src==='会诊沉淀').map(k=>`<tr><td>${esc(k.title)}</td><td>${esc(k.type)} · v${k.versions[0].v}</td><td>${k.ops}</td><td>${k.uses} 次引用 / ${k.views} 次查看</td><td>${sbadge(k.stat)}</td><td class="acts"><button class="btn ghost sm2" onclick="knVersions('${k.id}')">新版本</button><button class="btn red sm2" onclick="knDel('${k.id}')">删除</button></td></tr>`)),
review:()=>head('知识审核','手册、SOP、经验、视频、回写的统一审核入口。')+table(['内容','分类','来源','版本','状态','操作'],DB.kn.map(k=>`<tr><td>${esc(k.title)}</td><td>${esc(k.type)} · ${esc(k.src)}</td><td>${esc(k.origin)} · ${deptName(k.dept)}</td><td>v${k.versions[0].v} · ${k.versions[0].d}</td><td>${sbadge(k.stat)}</td><td class="acts">${k.stat==='审核中'?`<button class="btn sm2" onclick="knApprove('${k.id}',true)">通过发布</button><button class="btn red sm2" onclick="knApprove('${k.id}',false)">驳回</button>`:`<button class="btn ghost sm2" onclick="knVersions('${k.id}')">版本</button>`}</td></tr>`)),
history:()=>{const solved=DB.consults.filter(c=>c.stat==='已解决');const reuse=solved.reduce((s,c)=>s+c.solved.reuse,0),avg=Math.round(reuse/Math.max(1,solved.length));return head('解决历史','沉淀 → 复用 → 采纳 → 再优化的经验闭环。')+stats([['累计解决',solved.length+' 例'],['沉淀知识',DB.kn.filter(k=>k.src==='会诊沉淀').length+' 篇'],['平均复用',avg+' 次/篇'],['采纳率',solved.length?Math.round(solved.reduce((s,c)=>s+c.solved.acc,0)/solved.length)+'%':'--']])+`<div class="card"><h3>经验再利用闭环</h3><p class="dim">每例会诊解决后自动进入闭环：沉淀为 CASE → 推送到同类工位 → 记录复用与采纳 → 采纳数据反哺优化新版本。</p>${solved.map(c=>`<div class="loop"><span class="lstage done">解决</span><span class="arr">→</span><span class="lstage done">沉淀 ${esc(c.solved.case)}</span><span class="arr">→</span><span class="lstage">复用 ${c.solved.reuse} 次</span><span class="arr">→</span><span class="lstage">采纳率 ${c.solved.acc}%</span><span class="arr">→</span><button class="btn ghost sm2" onclick="histReuse('${c.id}')">再推广</button></div>`).join('')}</div>`}};
function personForm(id){const p=id?DB.people.find(x=>x.id===id):null;modal(`<h3>${p?'编辑人员':'添加人员'}</h3><div class="grid2"><div class="field"><label>姓名<input id="pf-n" value="${p?esc(p.n):''}"></label></div><div class="field"><label>部门<select id="pf-d">${DB.depts.map(d=>`<option value="${d.id}"${p&&p.dept===d.id?' selected':''}>${d.name}</option>`).join('')}</select></label></div></div><div class="grid2"><div class="field"><label>角色<select id="pf-r">${Object.keys(ROLENAME).map(k=>`<option value="${k}"${p&&p.role===k?' selected':''}>${ROLENAME[k]}</option>`).join('')}</select></label></div><div class="field"><label>状态<select id="pf-on"><option value="1"${p&&p.on?' selected':''}>在线</option><option value="0"${p&&!p.on?' selected':''}>离线</option></select></label></div></div><div class="field"><label>技能（逗号分隔）<input id="pf-sk" value="${p?esc(p.skills):''}"></label></div><div class="field"><label>工位授权（逗号分隔）<input id="pf-st" value="${p?esc(p.st):''}"></label></div><div class="macts"><button class="btn" onclick="personSave('${id||''}')">保存</button><button class="btn ghost" onclick="closeModal()">取消</button></div>`)}
function personSave(id){const g=x=>document.getElementById(x).value;const n=g('pf-n').trim();if(!n)return toast('请填写姓名');const data={n,dept:g('pf-d'),role:g('pf-r'),skills:g('pf-sk'),st:g('pf-st'),on:+g('pf-on')};if(id){Object.assign(DB.people.find(x=>x.id===id),data);audit('权限变更',n)}else{DB.people.push({id:'P'+Date.now()%10000,...data});audit('人员添加',n)}saveDB();closeModal();toast('人员已保存');render()}
function personDel(id){const p=DB.people.find(x=>x.id===id);if(!p)return;if(!confirm('删除人员「'+p.n+'」？'))return;DB.people=DB.people.filter(x=>x.id!==id);saveDB();audit('人员删除',p.n);toast('人员已删除');render()}
window.orgF={dept:'全部',role:'全部',on:'全部',kw:''};
function orgSet(f,v){window.orgF[f]=v;window.orgPg=0;orgList()}
function orgGo(p){window.orgPg=Math.max(0,p);orgList()}
function orgList(){const box=document.getElementById('org-box');if(!box)return;const f=window.orgF;let L=DB.people.slice();if(f.dept!=='全部')L=L.filter(p=>deptName(p.dept)===f.dept);if(f.role!=='全部')L=L.filter(p=>ROLENAME[p.role]===f.role);if(f.on!=='全部')L=L.filter(p=>(f.on==='在线')===!!p.on);if(f.kw)L=L.filter(p=>(p.n+p.skills+p.st).includes(f.kw));const PS=8;const total=Math.max(1,Math.ceil(L.length/PS));window.orgPg=Math.min(window.orgPg||0,total-1);const pg=window.orgPg;box.innerHTML=table(['人员','部门','角色','技能','工位授权','在线','操作'],L.slice(pg*PS,pg*PS+PS).map(p=>`<tr><td>${avatar(p.n)} ${esc(p.n)}</td><td>${deptName(p.dept)}</td><td>${ROLENAME[p.role]}</td><td>${esc(p.skills)||'--'}</td><td>${esc(p.st)||'--'}</td><td>${p.on?'<span class="badge">在线</span>':'<span class="badge dim">离线</span>'}</td><td class="acts"><button class="btn ghost sm2" onclick="personForm('${p.id}')">编辑</button><button class="btn red sm2" onclick="personDel('${p.id}')">删除</button></td></tr>`))+`<div class="pager"><button class="btn ghost sm2" onclick="orgGo(${pg-1})"${pg===0?' disabled':''}>上一页</button><span>第 ${pg+1} / ${total} 页 · 共 ${L.length} 人</span><button class="btn ghost sm2" onclick="orgGo(${pg+1})"${pg>=total-1?' disabled':''}>下一页</button></div>`}
function apQual(step){return DB.people.filter(p=>p.dept===step.dept&&p.role===step.role).length}
function apRender(id){const box=document.getElementById('ap-'+id);if(!box)return;const a=DB.ap.find(x=>x.id===id);box.innerHTML=`<div class="chain">${a.chain.map((s,i)=>`<div class="chstep"><div class="chrow"><select onchange="apSet('${id}',${i},'dept',this.value)">${DB.depts.map(d=>`<option value="${d.id}"${s.dept===d.id?' selected':''}>${d.name}</option>`).join('')}</select><select onchange="apSet('${id}',${i},'role',this.value)">${Object.keys(ROLENAME).map(k=>`<option value="${k}"${s.role===k?' selected':''}>${ROLENAME[k].split('/')[0]}</option>`).join('')}</select><button class="mx smx" onclick="apDelStep('${id}',${i})">×</button></div><small>${apQual(s)} 人可审批</small></div>${i<a.chain.length-1?'<span class="arr">→</span>':''}`).join('')}<button class="btn ghost sm2" onclick="apAddStep('${id}')">＋环节</button></div><div class="grid2"><div class="field"><label>时限<input value="${esc(a.sla)}" onchange="apSet2('${id}','sla',this.value)"></label></div><div class="field"><label>超时动作<input value="${esc(a.over)}" onchange="apSet2('${id}','over',this.value)"></label></div></div>`}
function apSet(id,i,f,v){const a=DB.ap.find(x=>x.id===id);a.chain[i][f]=v;saveDB();apRender(id);audit('审批策略调整',a.item)}
function apSet2(id,f,v){const a=DB.ap.find(x=>x.id===id);a[f]=v;saveDB();toast('已保存')}
function apAddStep(id){const a=DB.ap.find(x=>x.id===id);a.chain.push({dept:'D1',role:'leader'});saveDB();apRender(id)}
function apDelStep(id,i){const a=DB.ap.find(x=>x.id===id);if(a.chain.length<=1)return toast('至少保留一个环节');a.chain.splice(i,1);saveDB();apRender(id)}
function auF_(){window.auF=window.auF||{dept:'全部',act:'全部',who:'全部',range:'30天'};return window.auF}
function auList(){const f=auF_();const box=document.getElementById('au-box');if(!box)return;let L=DB.audit.slice();if(f.dept!=='全部')L=L.filter(a=>deptName(a.dept)===f.dept);if(f.act!=='全部')L=L.filter(a=>a.action===f.act);if(f.who!=='全部')L=L.filter(a=>a.who===f.who);if(f.range!=='全部'){const lim=f.range==='7天'?7:30;const cut=new Date(2026,10,26);cut.setDate(cut.getDate()-lim);L=L.filter(a=>{const p=a.d.split(' ')[0].split('-').map(Number);return new Date(2026,p[0]-1,p[1])>=cut})}const PS=12;window.auPg=window.auPg||0;const total=Math.max(1,Math.ceil(L.length/PS));if(window.auPg>total-1)window.auPg=total-1;const pg=window.auPg;box.innerHTML=table(['时间','人员','部门','动作','对象'],L.slice(pg*PS,pg*PS+PS).map(a=>`<tr><td>${a.d}</td><td>${avatar(a.who)} ${esc(a.who)}</td><td>${deptName(a.dept)}</td><td><span class="badge ${a.action.includes('SOS')?'danger':a.action.includes('权限')||a.action.includes('删除')?'warn':''}">${a.action}</span></td><td>${esc(a.target)}</td></tr>`))+`<div class="pager"><button class="btn ghost sm2" onclick="auGo(${pg-1})"${pg===0?' disabled':''}>上一页</button><span>第 ${pg+1} / ${total} 页 · 共 ${L.length} 条</span><button class="btn ghost sm2" onclick="auGo(${pg+1})"${pg>=total-1?' disabled':''}>下一页</button></div>`}
function auSet(f,v){auF_()[f]=v;window.auPg=0;auList()}
function auGo(p){window.auPg=Math.max(0,p);auList()}
function dashSet(){const m=window.dashM||'tasks',rg=window.dashR||'7天';const n=rg==='7天'?7:30;const L=D30.slice(-n);const map={tasks:{d:TR.tasks.slice(-n),n:'任务完成量',c:'#0aa68f'},acc:{d:TR.acc.slice(-n),n:'一次合格率 %',c:'#1f7ec2'},kn:{d:TR.kn.slice(-n),n:'知识新增',c:'#7c5cbf'},appr:{d:TR.appr.slice(-n),n:'审批量',c:'#f39446'}};const s=map[m];const el=document.getElementById('dash-chart');if(el)el.innerHTML=lineChart(L,[{n:s.n,c:s.c,data:s.d}],205);document.querySelectorAll('#dash-m .chip').forEach(c=>c.classList.toggle('on',c.dataset.m===m));document.querySelectorAll('#dash-r .chip').forEach(c=>c.classList.toggle('on',c.dataset.r===rg))}
function dashSetM(v){window.dashM=v;dashSet()}
function dashSetR(v){window.dashR=v;dashSet()}
function docEditorPage(type){const id=q.get('doc'),d=DB.docs.find(x=>x.id===id);if(!d)return head('文档不存在','可能已被删除。',`<a class="btn ghost" href="?page=${type}">返回列表</a>`);return head((type==='layout'?'工厂布局':'流程模板')+' · '+esc(d.name),(type==='layout'?'厂区、产线、工位、设备与物流动线。':'标准工序、审批、判断、返工和 SOS 流转。')+' 修改自动保存；发布后生成新版本。',`<a class="btn ghost" href="?page=${type}">← 返回列表</a><button class="btn" onclick="publishDoc('${d.id}');render()">发布 v${d.v}</button>`)+editor(type,{key:'doc.'+d.id,pk:type,seed:CSEED[type],doc:d,onSave:()=>{d.date=today();saveDB()}})}
P.master={home:()=>head('管理概览','全工厂使用统计、产线效率与知识资产趋势。图上数据点可点击查看当日详情。')+stats([['今日任务','46'],['完成率','91%'],['SOS','2'],['待审批','5'],['知识引用','128'],['审批均时','12m']])+`<div class="card"><div class="filters"><div class="chips" id="dash-m"><button class="chip" data-m="tasks" onclick="dashSetM('tasks')">任务完成量</button><button class="chip" data-m="acc" onclick="dashSetM('acc')">一次合格率</button><button class="chip" data-m="kn" onclick="dashSetM('kn')">知识新增</button><button class="chip" data-m="appr" onclick="dashSetM('appr')">审批量</button></div><div class="chips" id="dash-r"><button class="chip" data-r="7天" onclick="dashSetR('7天')">近 7 天</button><button class="chip" data-r="30天" onclick="dashSetR('30天')">近 30 天</button></div></div><div id="dash-chart"></div></div><div class="grid2"><div class="card"><h3>各产线当前使用率</h3>${hbars([['大连一厂 · Line A',78],['大连一厂 · Line B',62],['苏州二厂 · Line C',71],['青岛三厂 · 装配线',54]])}</div><div class="card"><h3>知识新增走势（近 14 天）</h3>${barChart(D30.slice(-14),TR.kn.slice(-14),'#7c5cbf')}<p class="dim">吸收中：${DB.depts.map(d=>d.name).join(' · ')}</p></div></div><div class="card"><h3>各产线一次合格率</h3><table class="table"><tr><th>产线</th><th>使用率</th><th>一次合格率</th><th>状态</th></tr>${[['L1',78,96.4],['L2',62,93.1],['L3',71,95.2],['L4',54,91.8]].map(x=>`<tr><td>${lineName(x[0])}</td><td>${x[1]}%</td><td>${x[2]}%</td><td>${x[2]>=95?'<span class="badge">健康</span>':'<span class="badge warn">关注</span>'}</td></tr>`).join('')}</table></div>`,
layout:()=>q.get('doc')?docEditorPage('layout'):docList('layout'),
flow:()=>q.get('doc')?docEditorPage('flow'):docList('flow'),
org:()=>head('组织权限','部门、人员、角色与工位授权的全厂管理，支持筛选与分页。','<button class="btn" onclick="personForm(\'\')">＋添加人员</button>')+`<div class="card"><h3>部门</h3><table class="table"><tr><th>部门</th><th>负责人</th><th>人数</th><th>覆盖产线</th><th>角色分布</th></tr>${DB.depts.map(d=>{const ps=DB.people.filter(p=>p.dept===d.id);const dist={};ps.forEach(p=>dist[p.role]=(dist[p.role]||0)+1);return `<tr><td>${d.name}</td><td>${esc(d.leader)}</td><td>${ps.length}</td><td>${esc(d.line)}</td><td>${Object.entries(dist).map(x=>`<span class="badge dim">${ROLENAME[x[0]].split('/')[0]} ×${x[1]}</span>`).join(' ')}</td></tr>`}).join('')}</table></div>`+`<div class="card"><div class="filters"><label>部门<select onchange="orgSet('dept',this.value)"><option>全部</option>${DB.depts.map(d=>`<option>${d.name}</option>`).join('')}</select></label><label>角色<select onchange="orgSet('role',this.value)"><option>全部</option>${Object.keys(ROLENAME).map(k=>`<option>${ROLENAME[k]}</option>`).join('')}</select></label><label>状态<select onchange="orgSet('on',this.value)"><option>全部</option><option>在线</option><option>离线</option></select></label><label>搜索<input class="insel" placeholder="姓名/技能" oninput="orgSet('kw',this.value)"></label></div></div><div id="org-box"></div>`+`<div class="card"><h3>角色权限矩阵</h3><table class="table"><tr><th>功能</th><th>操作员</th><th>作业长</th><th>专家</th><th>Master</th></tr>${[['任务执行与反馈','执行','本组','',''],['任务创建/分配','','本部门','',''],['人员添加/删除','','','','全厂'],['本部门人员权限','','✓','',''],['知识沉淀','','✓','✓','✓'],['知识发布审核','','','✓','✓'],['布局/模板管理','','','','✓'],['审批策略','','','','✓'],['审计追溯','本人','本部门','会诊相关','全厂']].map(row=>`<tr><td>${row[0]}</td>${row.slice(1).map(c=>`<td>${c?`<span class="badge">${c}</span>`:'<span class="dim">--</span>'}</td>`).join('')}</tr>`).join('')}</table><p class="dim">管理岗（作业长）登录后可在「任务管理 → 人员与权限」中调整本部门人员的技能与工位授权；人员增删仅 Master 可操作。</p></div>`,
review:()=>head('知识治理','使用吸收、正确率、版本与废弃的全生命周期治理。','<button class="btn" onclick="knNew()">＋新建知识</button>')+stats([['启用',DB.kn.filter(k=>k.stat==='启用').length],['审核中',DB.kn.filter(k=>k.stat==='审核中').length],['废弃',DB.kn.filter(k=>k.stat==='废弃').length],['总引用',DB.kn.reduce((s,k)=>s+k.uses,0)+' 次']])+table(['知识','类型/来源','使用部门','引用/查看','正确率','版本','状态','操作'],DB.kn.map(k=>`<tr><td>${esc(k.title)}</td><td>${esc(k.type)} · ${esc(k.origin)}</td><td>${k.depts?k.depts.split(',').map(deptName).join('、'):'<span class="dim">未被吸收</span>'}</td><td>${k.uses} / ${k.views}</td><td>${k.acc?k.acc+'%':'--'}</td><td><button class="btn ghost sm2" onclick="knVersions('${k.id}')">v${k.versions[0].v}（${k.versions.length}版）</button></td><td>${sbadge(k.stat)}</td><td class="acts"><button class="btn ghost sm2" onclick="knVersions('${k.id}')">替换新版</button><button class="btn ghost sm2" onclick="knStat('${k.id}','${k.stat==='废弃'?'启用':'废弃'}')">${k.stat==='废弃'?'恢复':'废弃'}</button><button class="btn red sm2" onclick="knDel('${k.id}')">删除</button></td></tr>`)),
approval:()=>head('审批策略','审批链与组织权限实时绑定：环节=部门+角色，可审批人数自动计算。')+DB.ap.map(a=>`<div class="card"><div class="doc-h"><b>${esc(a.item)}</b><span class="badge dim">触发：${esc(a.trig)}</span></div><div id="ap-${a.id}"></div></div>`).join('')+`<div class="card"><h3>绑定说明</h3><p class="dim">环节人员变动（组织权限中增删人员、调整角色）会实时影响「可审批人数」；为 0 时该环节标红并由上一环节自动升级。审批中心按此链路派单。</p></div>`,
history:()=>head('审计历史','全工厂全部门的操作留痕，支持部门/动作/人员/时间筛选。')+`<div class="card"><div class="filters"><label>部门<select onchange="auSet('dept',this.value)"><option>全部</option>${DB.depts.map(d=>`<option>${d.name}</option>`).join('')}</select></label><label>动作<select onchange="auSet('act',this.value)"><option>全部</option>${['登录','任务完成','审批通过','审批驳回','知识引用','知识推送','知识发布','SOS 升级','权限变更','人员添加','人员删除','模板发布','布局发布','版本更新','任务创建','任务删除'].map(a=>`<option>${a}</option>`).join('')}</select></label><label>人员<select onchange="auSet('who',this.value)"><option>全部</option>${[...new Set(DB.audit.map(a=>a.who))].map(w=>`<option>${esc(w)}</option>`).join('')}</select></label><label>范围<select onchange="auSet('range',this.value)"><option>7天</option><option>30天</option><option>全部</option></select></label></div></div><div id="au-box"></div>`};
function publishDoc(id){const docId=id||q.get('doc');const doc=DB.docs.find(x=>x.id===docId);if(!doc)return;doc.v++;doc.stat='已发布';doc.date=today();saveDB();audit(doc.type==='layout'?'布局发布':'模板发布',doc.name+' v'+doc.v);toast('已发布 v'+doc.v)}
function detail(){const t=DB.tasks.find(x=>x.id===q.get('id'))||DB.tasks[0];const kn=DB.kn.filter(k=>k.stat==='启用'&&k.ops.split(',').includes(t.op)).slice(0,2);return head(t.id+' · '+t.name,lineName(t.line)+' / '+t.st+' / '+t.op+' / '+(t.who||'未分配'),`<a class="btn ghost" href="javascript:history.back()">← 返回</a><button class="btn red" onclick="toast('SOS 已发出，作业长已收到')">SOS 求助</button>`)+flowbar()+videoCard(t)+`<div class="detail"><div class="card"><h3>现场状况</h3><p>${esc(t.desc)}</p><p><b>停留：</b>${t.time}　<b>下一步：</b>${esc(t.next)}</p><h3>证据</h3><div class="toolbar"><button class="btn ghost" onclick="toast('照片已上传并完成 OCR 提取')">＋照片</button><button class="btn ghost" onclick="toast('视频已上传，抽取关键帧')">＋视频</button><button class="btn ghost" onclick="toast('OCR 完成，读数已提取')">OCR</button><button class="btn ghost" onclick="toast('测量值已记录')">测量值</button></div><div class="field"><label>现场反馈<select><option>已解决</option><option>部分有效</option><option>不符合现场</option><option>安全风险</option></select></label></div><button class="btn" onclick="fbSubmit('${t.id}')">提交结果</button> <button class="btn red" onclick="toast('SOS 已发出')">SOS</button><h3>匹配知识</h3>${kn.map(k=>`<div class="trow sm"><div class="tinfo"><b>${esc(k.title)}</b><small>v${k.versions[0].v} · 正确率 ${k.acc}% · ${esc(k.type)}</small></div><button class="btn ghost sm2" onclick="kUse('${k.id}')">引用</button></div>`).join('')||'<p class="dim">暂无匹配知识</p>'}</div><aside class="card"><h3>任务轨迹</h3><div class="timeline"><p>任务已分配 → ${esc(t.who||'待分配')}</p><p>进入 ${t.st}（${t.op}）</p><p>现场证据已上传（照片 / 视频 / 测量）</p><p>${sbadge(t.status)} ${esc(t.next)}</p></div><h3>现场人员</h3><p>${avatar(t.who||'?')} ${esc(t.who||'未分配')} · 当前位于 ${t.st}</p></aside></div>`}
function pageTitle(){if(page==='detail')return '任务详情';if(page==='consult'&&q.get('id')){const c=DB.consults.find(x=>x.id===q.get('id'));if(c)return c.problem}const doc=q.get('doc');if(doc){const d=DB.docs.find(x=>x.id===doc);if(d)return d.name}const m=r.m.find(x=>x[1]===page);return m?m[0]:'工作台'}
function renderProf(){prof.innerHTML=`<div class="pfrow">${avatar(r.alias)}<div><b>${r.n}</b><br><small>${r.d} · ${ROLENAME[role]}</small></div></div><span class="on-dot" title="在线"></span>`}
function render(){renderProf();__cvOpts=null;window.__vid=null;content.innerHTML=page==='detail'?detail():(P[role][page]||P[role].home)();crumb.innerHTML=`<a href="?page=home">首页</a> <i>/</i> ${CRUMB[role][page]||'工作台'} <i>/</i> <b>${esc(pageTitle())}</b>`;if(__cvOpts&&document.getElementById('cv-stage')){window.__cv=Canvas(__cvOpts);const dn=document.getElementById('cv-docname');if(dn)dn.onchange=()=>{const d=DB.docs.find(x=>x.id===q.get('doc'));if(d){d.name=dn.value.trim()||d.name;saveDB();crumb.querySelector('b').textContent=d.name}}}initVideo();if(role==='operator'&&page==='tasks')opList();if(role==='leader'&&page==='tasks')tskList();if(role==='master'&&page==='history')auList();if(role==='master'&&page==='home')dashSet();if(role==='master'&&page==='approval')DB.ap.forEach(a=>apRender(a.id));if(role==='leader'&&page==='home'){ldChartDraw();if((window.ldTab2||'任务管理')==='任务管理')tskList()}if(role==='leader'&&page==='perm'){const pb=document.getElementById('perm-box');if(pb)pb.innerHTML=permPanel()}if(role==='operator'&&page==='home'&&window.opTab==='我的任务')opList();if(role==='master'&&page==='org')orgList()}
loadAvatars();
['operator','leader','expert','master'].forEach(k=>{P[k].me=mePage});
document.addEventListener('mousemove',e=>{const c=e.target&&e.target.closest?e.target.closest('.cpt'):null;if(!tipEl){tipEl=document.createElement('div');tipEl.id='chart-tip';document.body.appendChild(tipEl)}if(c){tipEl.style.display='block';tipEl.style.left=(e.clientX+12)+'px';tipEl.style.top=(e.clientY-34)+'px';tipEl.textContent=c.dataset.l+' · '+c.dataset.s+'：'+c.dataset.v}else tipEl.style.display='none'});
document.addEventListener('click',e=>{const c=e.target&&e.target.closest?e.target.closest('.cpt'):null;if(c)dayDetail(c.dataset.l,c.dataset.s,c.dataset.v)});
let tipEl=null;
prof.innerHTML=`<div class="pfrow">${avatar(r.alias)}<div><b>${r.n}</b><br><small>${r.d} · ${ROLENAME[role]}</small></div></div><span class="on-dot" title="在线"></span>`;
nav.innerHTML=r.m.map(x=>`<a href="?page=${x[1]}">${x[0]}</a>`).join('');
document.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('on',a.href.includes('page='+page)));
if(role==='master')tablet.style.display='none';
tablet.onclick=()=>{document.body.classList.toggle('tablet');tablet.textContent=document.body.classList.contains('tablet')?'桌面模式':'平板模式'};
render();
